sdl:
extend type EditingContext {
  expressionTextualRepresentation(elementId: ID!): ExpressionEditorState
}

type ExpressionEditorState {
  textualRepresentation: String!
  featureValueProperties: FeatureValueExpressionProperties
}

type FeatureValueExpressionProperties {
  isDefault: Boolean!
  isInitial: Boolean!
}

extend type Mutation {
  deleteExpression(input: DeleteExpressionInput!): DeleteExpressionPayload!
}

input DeleteExpressionInput {
  id: ID!
  editingContextId: String!
  parentElementId: String!
}

union DeleteExpressionPayload = ErrorPayload | SuccessPayload

extend type Mutation {
  insertTextualSysMLv2(input: InsertTextualSysMLv2Input!): InsertTextualSysMLv2Payload!
}

input InsertTextualSysMLv2Input {
  id: ID!
  editingContextId: ID!
  objectId: ID!
  textualContent: String!
}

union InsertTextualSysMLv2Payload = ErrorPayload | SuccessPayload

extend type Mutation {
  createExpression(input: CreateExpressionInput!): CreateExpressionPayload!
  editExpression(input: EditExpressionInput!): EditExpressionPayload!
}

input CreateExpressionInput {
  id: ID!
  editingContextId: ID!
  parentElementId: ID!
  expressionText: String!
  properties: ExpressionPropertiesInput
}

union CreateExpressionPayload = ErrorPayload | CreateExpressionSuccessPayload

type CreateExpressionSuccessPayload {
  id: ID!
  newExpressionId: ID!
  messages: [Message]!
}

input EditExpressionInput {
  id: ID!
  editingContextId: ID!
  elementId: ID!
  newExpressionText: String!
  properties: ExpressionPropertiesInput
}

input ExpressionPropertiesInput {
  featureValue: FeatureValueExpressionPropertiesInput
}

input FeatureValueExpressionPropertiesInput {
  isDefault: Boolean
  isInitial: Boolean
}

union EditExpressionPayload = ErrorPayload | EditExpressionSuccessPayload

type EditExpressionSuccessPayload {
  id: ID!
  newExpressionId: ID!
  messages: [Message]!
}

extend type Viewer {
  showDiagramsIconsValue: Boolean!
  showDiagramsInheritedMembersValue: Boolean!
  showDiagramsInheritedMembersFromStandardLibrariesValue: Boolean!
}

extend type Mutation {
  showDiagramsIcons(input: ShowDiagramsIconsInput!): ShowDiagramsIconsPayload!
  showDiagramsInheritedMembers(input: ShowDiagramsInheritedMembersInput!): ShowDiagramsInheritedMembersPayload!
  showDiagramsInheritedMembersFromStandardLibraries(input: ShowDiagramsInheritedMembersFromStandardLibrariesInput!): ShowDiagramsInheritedMembersFromStandardLibrariesPayload!
}

input ShowDiagramsIconsInput {
  id: ID!
  editingContextId: ID!
  representationId: ID!
  show: Boolean!
}

union ShowDiagramsIconsPayload = ErrorPayload | ShowDiagramsIconsSuccessPayload

type ShowDiagramsIconsSuccessPayload {
  id: ID!
  show: Boolean!
}

input ShowDiagramsInheritedMembersInput {
  id: ID!
  editingContextId: ID!
  representationId: ID!
  show: Boolean!
}

union ShowDiagramsInheritedMembersPayload = ErrorPayload | ShowDiagramsInheritedMembersSuccessPayload

type ShowDiagramsInheritedMembersSuccessPayload {
  id: ID!
  show: Boolean!
}

input ShowDiagramsInheritedMembersFromStandardLibrariesInput {
  id: ID!
  editingContextId: ID!
  representationId: ID!
  show: Boolean!
}

union ShowDiagramsInheritedMembersFromStandardLibrariesPayload = ErrorPayload | ShowDiagramsInheritedMembersFromStandardLibrariesSuccessPayload

type ShowDiagramsInheritedMembersFromStandardLibrariesSuccessPayload {
  id: ID!
  show: Boolean!
}
